function make_palindrome(string){
  const reverse = s => s.split('').reverse().join('');
  for (let i = 0; i < string.length; i++) {
    const suffix = string.slice(i);
    if (suffix === reverse(suffix)) {
      return string + reverse(string.slice(0, i));
    }
  }
  return string;
}

