HumanEval_160_do_algebra.solution:
function do_algebra(operator, operand){
  // Python precedence: ** (right-associative), then * and //, then + and -.
  let values = operand.slice();
  let ops = operator.slice();
  for (let i = ops.length - 1; i >= 0; i--) {
    if (ops[i] === '**') {
      values.splice(i, 2, Math.pow(values[i], values[i + 1]));
      ops.splice(i, 1);
    }
  }
  for (let i = 0; i < ops.length; ) {
    if (ops[i] === '*' || ops[i] === '//') {
      const result = ops[i] === '*' ? values[i] * values[i + 1] : Math.floor(values[i] / values[i + 1]);
      values.splice(i, 2, result);
      ops.splice(i, 1);
    } else {
      i++;
    }
  }
  let total = values[0];
  for (let i = 0; i < ops.length; i++) {
    total = ops[i] === '+' ? total + values[i + 1] : total - values[i + 1];
  }
  return total;
}

