HumanEval_153_Strongest_Extension.solution:
function Strongest_Extension(class_name, extensions) {
  const strength = (e) => {
    let s = 0;
    for (const c of e) {
      if (c >= "A" && c <= "Z") s++;
      else if (c >= "a" && c <= "z") s--;
    }
    return s;
  };
  let best = extensions[0];
  for (const e of extensions) {
    if (strength(e) > strength(best)) best = e;
  }
  return class_name + "." + best;
}

