function get_odd_collatz(n) {
  const odds = [];
  while (true) {
    if (n % 2 === 1) odds.push(n);
    if (n === 1) break;
    n = n % 2 === 0 ? n / 2 : 3 * n + 1;
  }
  return odds.sort((a, b) => a - b);
}

