function check_if_last_char_is_a_letter(txt) {
  if (txt.length === 0) return false;
  const last = txt[txt.length - 1];
  if (!/[a-zA-Z]/.test(last)) return false;
  return txt.length === 1 || txt[txt.length - 2] === " ";
}

