function minSubArraySum(nums) {
  let best = nums[0];
  let cur = nums[0];
  for (let i = 1; i < nums.length; i++) {
    cur = Math.min(nums[i], cur + nums[i]);
    best = Math.min(best, cur);
  }
  return best;
}

