function strange_sort_list(lst) {
  const sorted = [...lst].sort((a, b) => a - b);
  const out = [];
  let lo = 0, hi = sorted.length - 1;
  while (lo <= hi) {
    out.push(sorted[lo++]);
    if (lo <= hi) out.push(sorted[hi--]);
  }
  return out;
}

